INSERT INTO verticalizzazioniparametribase(modulo, parametro, descrizione) VALUES('PROTOCOLLO_SIPRWEB', 'USA_WS_CLASSIFICHE','Indica se per il recupero delle classifiche, sull''albero degli interventi, debba essere usato il metodo messo a disposizione del web service (valore = 1) oppure no (valore 0, vuoto o non presente). E'' stato deciso di inserire questo parametro in quanto recuperare le classifiche da web service potrebbe essere macchinoso rendendo la pagina del dettaglio degli interventi molto lenta se i dati dovessero essere molti. Oltre tutto i dati potrebbero creare una lunga lista difficilmente leggibile dagli utenti. In ultimo, se dovesso essere modificati i codici, questi non sarebbero più direttamente visibili sul campo Classifica nel dettaglio degli interventi in quanto non più presenti nella lista.');
INSERT INTO verticalizzazioniparametribase(modulo, parametro, descrizione) VALUES('PROTOCOLLO_SIPRWEB', 'USA_WS_TIPIDOC','Indica se per il recupero delle tipologie di documento, sull''albero degli interventi, debba essere usato il metodo messo a disposizione del web service (valore = 1) oppure no (valore 0, vuoto o non presente). E'' stato deciso di inserire questo parametro in quanto recuperare le tipologie di documento da web service potrebbe essere macchinoso rendendo la pagina del dettaglio degli interventi molto lenta se i dati dovessero essere molti. Oltre tutto i dati potrebbero creare una lunga lista difficilmente leggibile dagli utenti. In ultimo, se dovesso essere modificati i codici'); 
