INSERT INTO verticalizzazioniparametribase(modulo, parametro, descrizione) VALUES('PROTOCOLLO_IRIDE', 'SWAP_EMAIL', 'Valido solo per Iride2, è un tag che indica che tipo di comportamento deve assumere il recapito EMAIL, se il tag NON è presente oppure è presente con un qualsiasi valore diverso da S, il ws si comporta come ha sempre fatto (inserisce anagrafica se non esiste o va in aggiornamento sul tipo recapito indicato), se il tag è presente con il valore S esegue le seguenti operazioni: a) se il recapito per quel tipo e quel valore (considerando la valutazione case insensitive) esiste non si esegue nulla b) se il recapito per quel tipo esiste ma con valore diverso occorre: se non esiste un TipoRecapito X col valore attuale del recapito se ne inserisce uno nuovo dove X e’ il primo disponibile e successivamente si aggiorna il recapito con il VALORERECAPITO, se invece esiste lo stesso recapito sarà classificato come primo della lista.');
INSERT INTO SOFTWARE (CODICE, DESCRIZIONE, MODULOOPZIONALE, DESCRIZIONELUNGA, ACCESSORAPIDO, ORDINE) VALUES ('SG', 'Supporto Giuridico e Suap', '1', 'Supporto Giuridico e Suap', '0', '53');
INSERT INTO verticalizzazioniparametribase(modulo, parametro, descrizione) VALUES('PROTOCOLLO_DOCAREA', 'USA_DENOMINAZIONE_PG', 'Questo parametro indica se il componente che crea la segnatura da inviare come request al web service DOCAREA deve inserire la ragione sociale della persona giuridica sull''elemento <DENOMINAZIONE> presente dentro al nodo <MITTENTE> o <DESTINATARIO> (valore = a 1), o sull''elemento <COGNOME> (non presente, non valorizzato o valore diverso da 1); questo parametro si è reso necessario per il protocollo DocArea in quanto il web service installato da Maggioli (ad esempio Comune di Lucca) ha un limite, sull''elemento <COGNOME> che è quello che viene valorizzato di default con la Ragione Sociale della persona giuridica, di 40 caratteri, e può succedere di avere delle ragioni sociali più lunghe, quindi valorizzando a 1 questo parametro, la ragione sociale stessa verrebbe dirottata sull''elemento <DENOMINAZIONE>, che non ha limiti. Il web service DocArea di altre aziende (ad esempio Ads) non avendo limiti di lunghezza, non permette questo tipo di sistema, richiedendo che la ragione sociale passi necessariamente sull''elemento <COGNOME>, in questo caso questo parametro non va valorizzato (o comunque non va valorizzato a 1)'); 
INSERT INTO verticalizzazioniparametribase(modulo, parametro, descrizione) VALUES('PROTOCOLLO_DOCAREA', 'MULTI_MITT_DEST', 'Questo parametro indica se il componente che crea la segnatura da inviare come request al web service DOCAREA debba inviare tutte le anagrafiche che arrivano dal backoffice (valore uguale a 1), oppure solo la prima (non presente, valore vuoto o qualsiasi altro valore diverso da 1); in teoria, da specifiche DOCAREA non sarebbe possibile inviare più anagrafiche come MITTENTI / DESTINATARI, usare quindi questo parametro solamente in casi particolari dove il web service fornito dal fornitore di protocollo non tenga conto di questa regola'); 
INSERT INTO LAYOUTPAGINEBASE (LP_OGGETTO, DESCRIZIONE) VALUES ('fldCodicePraticaTelematica', 'Mostra o nasconde nella scheda istanza il campo CODICE_PRATICA_TELEMATICA');
